# region: fold
def fold(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.lstrip('-').isdigit():
            out.append(int(s))
    return out

# region: render
def render(xs, factor=3):
    return [v * factor for v in xs]

# region: sift
def sift(xs):
    return {'n': len(xs), 'total': max(xs)}

# region: shape
def shape(summary, bar=2):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return shape(sift(render(fold(raw))))

